    values.sort(key=lambda x: (x[1], x[0]))

    # Group by y position
    by_y = {}
    for x, y, text in values:
        y_key = round(y)
        if y_key not in by_y:
            by_y[y_key] = []
        by_y[y_key].append((x, text))

    # Now let's map these to years and quarters
    # From the y axis labels, Q1 is at I position, Q2 is at IV position

    # Year column centers based on x positions
    year_centers = {'2004': 382, '2005': 449, '2006': 509, '2007': 555}

