from html.parser import HTMLParser

content = open('/app/resources/treasury_bulletin_1970_06_page_89.txt', 'r').read()

class TableParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_td = False
        self.in_tr = False
        self.current_row = []
        self.rows = []

    def handle_starttag(self, tag, attrs):
        if tag == 'tr':
            self.in_tr = True
            self.current_row = []
        elif tag == 'td' or tag == 'th':
            self.in_td = True

    def handle_endtag(self, tag):
        if tag == 'td' or tag == 'th':
            self.in_td = False
        elif tag == 'tr':
            if self.current_row:
                self.rows.append(self.current_row)
            self.in_tr = False

    def handle_data(self, data):
        if self.in_td:
            self.current_row.append(data.strip())

parser = TableParser()
parser.feed(content)

# Print all rows to understand the full structure
for i, row in enumerate(parser.rows):
    print(f"Row {i}: {row}")
