import json

# Function to extract on/off budget receipts from JSON
def extract_receipts(json_file):
    with open(json_file) as f:
        data = json.load(f)

    receipts = {}
    for elem in data['document']['elements']:
        content = elem.get('content', '') or ''
        if 'On-budget receipts' in content and 'Off-budget receipts' in content:
            # Parse the table
            import re
            # Look for fiscal year data rows
            rows = re.findall(r'<tr><td>(\d{4[^}]+|[^<]+)</td><td>([^<]+)</td><td>([^<]+)</td><td>([^<]+)</td>', content)
            for row in rows:
                year = row[0].strip()
                # Clean up year (remove footnotes like <sup>1</sup>)
                year = re.sub(r'<sup[^>]*>[^<]*</sup>', '', year).strip()
                if year.isdigit() and 1990 <= int(year) <= 2010:
                    on_budget = row[2].strip().replace(',', '')
                    off_budget = row[3].strip().replace(',', '')
                    try:
                        receipts[int(year)] = {
                            'on_budget': float(on_budget),
                            'off_budget': float(off_budget)
                        }
                    except:
                        pass

    return receipts

# Process all bulletins
files = [
    '/app/resources/treasury_bulletin_1996_09.json',
    '/app/resources/treasury_bulletin_2001_09.json',
    '/app/resources/treasury_bulletin_2006_09.json',
    '/app/resources/treasury_bulletin_2011_09.json'
]

all_receipts = {}
for f in files:
    rec = extract_receipts(f)
    all_receipts.update(rec)
    print(f"From {f.split('/')[-1]}: Found {len(rec)} years")

# Sort and print
for year in sorted(all_receipts.keys()):
    print(f"{year}: On-budget={all_receipts[year]['on_budget']}, Off-budget={all_receipts[year]['off_budget']}")
