def compute_3month_ma(yields):
    result = {}
    for i, m in enumerate(months):
        if i >= 2:  # March onwards (index 2)
            # 3-month moving average: avg of current month and 2 previous
            vals = [yields[months[i-2]], yields[months[i-1]], yields[m]]
