import json

# Comprehensive search for anything with CAD or Canadian in both bulletins
files = ['/app/resources/treasury_bulletin_1960_01.json', '/app/resources/treasury_bulletin_1960_02.json']

for filepath in files:
    with open(filepath) as f:
        data = json.load(f)

    def search(obj, path=''):
        if isinstance(obj, dict):
            for k, v in obj.items():
                search(v, f'{path}.{k}')
        elif isinstance(obj, list):
            for i, item in enumerate(obj):
                search(item, f'{path}[{i}]')
        elif isinstance(obj, str):
            if 'Canada' in obj or 'CAD' in obj or 'Canadian dollar' in obj:
                print(f'{path}: {obj[:200]}')

    print(f'=== Searching {filepath} ===')
    search(data)
